"""Contextual help for BGIRS Data Pipeline -> Phase A: Generation."""
GENERATION_HELP_ENTRIES={
"subpage.data_pipeline.phase_a_generation":{"title":"Phase A: Generation","summary":"Own and inspect EnergyPlus Generation campaigns.","details":"Generation is the first workflow in the primary data/modeling hierarchy. This functional page owns Generation setup, validation, execution policy, results, diagnostics, and generated-data visualization. The Campaigns page may discover these campaigns but must not create or execute them."},
"generation.page.setup":{"title":"Generation Setup","summary":"Inspect known dataset roles and resolved campaign roots.","details":"Patch 1 is read-only. Known roles distinguish the small validated testing dataset from the full compact P1 paper dataset and provide authoritative expected counts."},
"generation.page.validation":{"title":"Generation Validation","summary":"Compare detected artifacts with expected role-specific counts.","details":"Known profiles validate case folders, latest_run.json files, RDD intersection manifests, parquet and pickle counts, and tracebacks. Requested but RDD-unavailable signals are not failures."},
"generation.page.execution":{"title":"Generation Execution","summary":"Review commands and safety boundaries without launching work.","details":"No execution callbacks exist in Patch 1. Full production generation, rerun-completed behavior, and deletion remain CLI-only."},
"generation.page.results":{"title":"Generation Results","summary":"Discover campaign metadata and prepare selected-data visualization.","details":"The Results tab scans campaign metadata without opening all parquet payloads. Later stages will load only the selected case, signal, and time range."},
"generation.page.diagnostics":{"title":"Generation Diagnostics","summary":"Inspect campaign completeness and failure indicators.","details":"Diagnostics distinguish valid RDD skips from missing artifacts, incomplete campaigns, tracebacks, and campaigns absent from the current machine."},
"generation.input.dataset_role":{"title":"Dataset Role","summary":"Classify a campaign as testing, full paper, or custom.","details":"Dataset role determines expected case and artifact counts and intended use. Testing is for smoke and development; Full Paper P1 is the validated 16-case upstream source."},
"generation.input.visualization_campaign":{"title":"Visualization Campaign","summary":"Select which Generation campaign will supply plot metadata.","details":"Known and discovered campaigns appear here. Patch 1 keeps the selector disabled until case/signal adapters and callbacks are validated."},
"generation.output.campaigns_root":{"title":"Campaigns Root","summary":"Current-machine root scanned for campaigns.","details":"This path is resolved from the live ScaleBridge generated-data root and points to its campaigns directory. BGIRS does not invent remote-machine paths."},
"generation.output.testing_command":{"title":"Testing Generation Command","summary":"Validated one-case testing command preview.","details":"This command targets RestaurantFastFood/Buffalo with one variable worker, RDD filtering, legacy pickles, and strict MLflow logging. It is displayed only and is not executed."},
"generation.output.full_command":{"title":"Full Paper Generation Command","summary":"Validated 16-case compact P1 command preview.","details":"This long-running command remains CLI-only until process lifecycle, cancellation, logging, and recovery are validated in BGIRS."},
"generation.metric.known_profiles":{"title":"Known Profiles","summary":"Number of first-class Generation dataset roles.","details":"Patch 1 defines the validated testing dataset and Full Paper P1 dataset as first-class roles."},
"generation.metric.campaigns_found":{"title":"Campaigns Found","summary":"Known campaign folders present on this machine.","details":"A campaign is found when its configured campaign root exists under the current ScaleBridge generated-data root."},
"generation.metric.profiles_complete":{"title":"Profiles Complete","summary":"Known campaigns whose discovered counts match expectations.","details":"Completeness requires all configured case, manifest, parquet, pickle, and traceback count checks to match."},
"generation.table.known_profiles":{"title":"Known Generation Profiles","summary":"Authoritative role and expected-count registry.","details":"This table explains campaign identity, scientific scope, expected cases and parquet artifacts, and intended use."},
"generation.table.validation":{"title":"Generation Artifact Validation","summary":"Detected artifact counts and validation status.","details":"Counts are collected without opening parquet files. A mismatch means the known profile is incomplete on the current machine or the artifact contract has changed."},
"generation.table.discovered_campaigns":{"title":"Discovered Generation Campaigns","summary":"Campaign folders containing generation/cases.","details":"Discovery is read-only. Custom campaigns are listed as discovered but do not receive hardcoded expected-count validation."},
"generation.section.command_preview":{"title":"Command Preview","summary":"Show the intended CLI structure without execution.","details":"Previewing a command has no side effect and does not create campaign folders or MLflow runs."},
"generation.section.validation_interpretation":{"title":"Validation Interpretation","summary":"Meaning of complete, incomplete, and not-found states.","details":"Complete matches the known profile; incomplete has one or more mismatches; not found means the campaign is absent from this machine."},
"generation.section.run_policy":{"title":"Execution Safety Policy","summary":"Separate read-only, confirmation-required, and CLI-only actions.","details":"Patch 1 exposes no process-launch controls. Production runs, deletion, and rerun-completed remain CLI-only."},
"generation.section.campaign_diagnostics":{"title":"Campaign Diagnostic Summary","summary":"Detailed messages for one known Generation campaign.","details":"Messages identify absent campaign roots or each expected-count mismatch detected by the read-only scan."},
"generation.plot.generated_signal":{"title":"Generated Signal Plot","summary":"Future time-series view for one selected parquet signal.","details":"The page must not eagerly load the full campaign. A future patch will inspect a selected parquet schema and load only the chosen case, signal, and time range."},
}
